fn parse_probe_json(json: &serde_json::Value) -> Option<ProbedMeta> {
    let format = json.get("format")?;
    let tags = format.get("tags").and_then(|t| t.as_object());
    // ffprobe uses the container's own tag naming — Vorbis lowercases, MP4 uses
    // `©nam`/`©ART`, ID3 exposes friendly aliases. Match case-insensitively so
    // we cover MP3/FLAC/OGG/OPUS uniformly.
    let get_tag = |name: &str| -> Option<String> {
        tags.and_then(|t| {
            t.iter().find_map(|(k, v)| {
                if k.eq_ignore_ascii_case(name) {
                    v.as_str().map(|s| s.trim().to_string()).filter(|s| !s.is_empty())
                } else {
                    None
                }
            })
        })
    };

    let length_ms = format
        .get("duration")
        .and_then(|v| v.as_str())
        .and_then(|s| s.parse::<f64>().ok())
        .filter(|d| d.is_finite() && *d > 0.0)
        .map(|d| (d * 1000.0) as i64);

    let title = get_tag("title");
    let author = get_tag("artist")
        .or_else(|| get_tag("album_artist"))
        .or_else(|| get_tag("performer"));

    if title.is_none() && author.is_none() && length_ms.is_none() {
        return None;
    }
    Some(ProbedMeta { title, author, length_ms })
}
