    async fn stalled_internal_file_url_bypasses_probe() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let addr: std::net::SocketAddr = listener.local_addr().unwrap();
        // Accept exactly one connection and never respond, so any HEAD probe
        // the current code issues gets stuck open until the outer timeout.
        tokio::spawn(async move {
            let (_stream, _) = listener.accept().await.unwrap();
            std::future::pending::<()>().await;
        });

        let client = reqwest::Client::builder()
            .proxy(reqwest::Proxy::all(format!("http://{addr}")).unwrap())
            .build()
            .unwrap();
        let source = DirectUrlSource { client };

        let result = tokio::time::timeout(
            Duration::from_millis(250),
            source.load("http://music.kena.lan/file/454137166"),
        )
        .await
        .expect("internal file URL must resolve without a network probe")
        .expect("load must succeed");

        match result {
            LoadResult::Track { data } => {
                let info = data.info;
                assert!(!info.is_stream);
                assert!(info.is_seekable);
                assert_eq!(info.source_name, "http");
                assert_eq!(
                    info.uri,
                    Some("http://music.kena.lan/file/454137166".to_string())
                );
            }
            other => panic!("expected LoadResult::Track, got {other:?}"),
        }
    }
