105	/// First occurrence of `key` in the raw query string. Mirrors the TS
106	/// `firstString` guard for clients that emit duplicate keys (`?q=a&q=b`).
107	fn query_first(raw: Option<&str>, key: &str) -> Option<String> {
108	    url::form_urlencoded::parse(raw?.as_bytes())
109	        .find(|(k, _)| k == key)
110	        .map(|(_, v)| v.into_owned())
111	}
