//! Port of `deezer-controller.ts` (prefix `/deezer`, 8 routes).
//!
//! Adaptador fino tras la Fase 2 del refactor: la orquestación de archivos
//! (locks, pipeline de descarga, mp3val, manifiestos, contador) vive en
//! `crate::system::deezer_files`; aquí solo queda la traducción HTTP —
//! parseo de rutas/query, envelopes a `Response` y el streaming con soporte
//! `Range` (RFC 7233) sobre el `AudioServe::File` que devuelve el núcleo.
//!
//! Observable contract (mirrored exactly):
//! - `/health` -> 200 `"OK"` / 500 `"UNAVAILABLE"` (no envelope error).
//! - `/tracks/{id}` + `/tracks/by-isrc/{isrc}` -> provider envelope
//!   pass-through, 404 fallback handled inside the provider (`DeezerResult`
//!   errors carry their own status).
//! - `/tracks/{id}/tokens` -> session tokens + cached track token, 401 on
//!   license errors, 500 on transport failures.
//! - `/tracks/{id}/file/{format}`, `/file`, `/file/only-cache` y
//!   `/file/{format}/only-cache` -> ver `system::deezer_files` (casos 5-8
//!   del catálogo docs/CASOS_DE_USO.md).
//! - `/autocomplete` + `/search` -> query normalizada (NFKC + invisibles),
//!   `limit` 1..=25 (default 10); fallos upstream se aplanan a payload vacío.

use std::path::Path as FsPath;

use axum::extract::{Extension, Path, RawQuery, State};
use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde::Serialize;
use serde_json::Value;

use crate::audio::{file_response, parse_range};
use crate::cache::keys::normalize_query_text;
use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
use crate::providers::deezer::DeezerTrackInfo;
use crate::state::AppState;
use crate::system::{AudioServe, Tipo};
use crate::telemetry::BandwidthOp;

const SEARCH_LIMIT_MIN: i64 = 1;
const SEARCH_LIMIT_MAX: i64 = 25;
const SEARCH_LIMIT_DEFAULT: i64 = 10;

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

fn response_with_status<T: Serialize>(status: StatusCode, result: ResultEnvelope<T>) -> Response {
    (status, Json(result)).into_response()
}

fn validation_error(message: &'static str) -> ApiError {
    ApiError::new(message, ErrorType::Validation, ErrorContext::Api).with_status(400)
}

fn internal_500<T: Serialize>() -> Response {
    let mut result = ResultEnvelope::<T>::new();
    result.add_error(
        &ApiError::new(
            "Internal server error",
            ErrorType::Internal,
            ErrorContext::Api,
        )
        .with_status(500),
    );
    result.into_response()
}

/// Stream the cached file honouring `Range` (the `sendFile` surface).
async fn send_cached_file(headers: &HeaderMap, path: &FsPath, content_type: &str) -> Response {
    let size = match tokio::fs::metadata(path).await {
        Ok(meta) => meta.len(),
        Err(err) => {
            tracing::error!(target: "DEEZER", error = %err, "sendFile stat failed");
            return internal_500::<()>();
        }
    };
    let range = headers
        .get(header::RANGE)
        .and_then(|value| value.to_str().ok());
    file_response(
        path,
        size,
        parse_range(range, size),
        content_type,
        HeaderMap::new(),
    )
    .await
}

/// Traducción `AudioServe` -> HTTP: archivo con Range, fallo como envelope
/// (el envelope emite status derivado + `x-error-code`/`x-error-type`).
async fn serve_outcome(headers: &HeaderMap, outcome: AudioServe) -> Response {
    match outcome {
        AudioServe::File { path, content_type } => {
            send_cached_file(headers, &path, content_type).await
        }
        AudioServe::Fail(envelope) => envelope.into_response(),
    }
}

// ---------------------------------------------------------------------------
// Search-query parsing (deezer-controller.ts:711-748)
// ---------------------------------------------------------------------------

/// First occurrence of `key` in the raw query string. Mirrors the TS
/// `firstString` guard for clients that emit duplicate keys (`?q=a&q=b`).
fn query_first(raw: Option<&str>, key: &str) -> Option<String> {
    url::form_urlencoded::parse(raw?.as_bytes())
        .find(|(k, _)| k == key)
        .map(|(_, v)| v.into_owned())
}

/// `Number.parseInt(s, 10)`: optional sign + leading decimal digits, `None`
/// when no digits lead the (trimmed) input.
fn parse_int_prefix(raw: &str) -> Option<i64> {
    let s = raw.trim_start();
    let (negative, rest) = match s.as_bytes().first() {
        Some(b'-') => (true, &s[1..]),
        Some(b'+') => (false, &s[1..]),
        _ => (false, s),
    };
    let digits = rest
        .as_bytes()
        .iter()
        .take_while(|b| b.is_ascii_digit())
        .count();
    if digits == 0 {
        return None;
    }
    let magnitude =
        rest[..digits]
            .parse::<i64>()
            .unwrap_or(if negative { i64::MIN } else { i64::MAX });
    Some(if negative { -magnitude } else { magnitude })
}

struct ParsedSearchQuery {
    q: String,
    limit: i64,
    errors: Vec<&'static str>,
}

fn parse_search_query(raw: Option<&str>) -> ParsedSearchQuery {
    let q = normalize_query_text(&query_first(raw, "q").unwrap_or_default());
    let limit_raw = query_first(raw, "limit").unwrap_or_default();
    // TS: `limitRaw ? parseInt(limitRaw) : NaN`, and NaN selects the default.
    let limit = if limit_raw.is_empty() {
        None
    } else {
        parse_int_prefix(&limit_raw)
    };

    let mut errors = Vec::new();
    if q.is_empty() {
        errors.push("Query parameter `q` is required");
    }
    if let Some(limit) = limit {
        if !(SEARCH_LIMIT_MIN..=SEARCH_LIMIT_MAX).contains(&limit) {
            errors.push("Query parameter `limit` must be between 1 and 25");
        }
    }

    ParsedSearchQuery {
        q,
        limit: limit.unwrap_or(SEARCH_LIMIT_DEFAULT),
        errors,
    }
}

// ---------------------------------------------------------------------------
// Handlers
// ---------------------------------------------------------------------------

/// `getHealthHandler` — 200 "OK" / 500 "UNAVAILABLE".
pub async fn get_health(
    State(state): State<AppState>,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let healthy = state.system.salud(Tipo::Deezer, bw).await;

    let mut result = ResultEnvelope::<&'static str>::new();
    result.add_data(if healthy { "OK" } else { "UNAVAILABLE" });
    if healthy {
        result.into_response()
    } else {
        response_with_status(StatusCode::INTERNAL_SERVER_ERROR, result)
    }
}

/// `getTrackInfoHandler` — `GET /deezer/tracks/{track_id}`.
pub async fn get_track_info(
    State(state): State<AppState>,
    Path(track_id): Path<String>,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let mut result = ResultEnvelope::<DeezerTrackInfo>::new();
    tracing::debug!(target: "DEEZER", track_id, "getTrackInfo controller input");

    match state.system.cancion_info(&track_id, bw).await {
        Ok(info) => {
            tracing::debug!(
                target: "DEEZER",
                track_id,
                isrc = ?info.isrc,
                "getTrackInfo controller response"
            );
            result.add_data(info);
            result.into_response()
        }
        Err(errors) => {
            for error in &errors {
                result.add_error(error);
            }
            result.into_response()
        }
    }
}

/// `getTrackByIsrcHandler` — `GET /deezer/tracks/by-isrc/{isrc}`.
pub async fn get_track_by_isrc(
    State(state): State<AppState>,
    Path(isrc): Path<String>,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let mut result = ResultEnvelope::<DeezerTrackInfo>::new();
    tracing::debug!(target: "DEEZER", isrc, "getTrackByIsrc controller input");

    match state.system.cancion_info_por_isrc(&isrc, bw).await {
        Ok(info) => {
            tracing::debug!(
                target: "DEEZER",
                isrc,
                deezer_track_id = %info.id,
                "getTrackByIsrc controller response"
            );
            result.add_data(info);
            result.into_response()
        }
        Err(errors) => {
            for error in &errors {
                result.add_error(error);
            }
            result.into_response()
        }
    }
}

/// `getTrackTokensHandler` — `GET /deezer/tracks/{track_id}/tokens`.
pub async fn get_track_tokens(
    State(state): State<AppState>,
    Path(track_id): Path<String>,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    state.system.cancion_tokens(&track_id, bw).await.into_response()
}

/// `GET /deezer/tracks/{track_id}/available-formats`.
pub async fn get_track_available_formats(
    State(state): State<AppState>,
    Path(track_id): Path<String>,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    state.system.cancion_formatos(&track_id, bw).await.into_response()
}

/// `getTrackFileHandler` — `GET /deezer/tracks/{track_id}/file/{format}`.
pub async fn get_track_file(
    State(state): State<AppState>,
    Path((track_id, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state.system.cancion_archivo(&track_id, &raw_format, bw).await;
    serve_outcome(&headers, outcome).await
}

/// `GET /deezer/tracks/{track_id}/file` — format omitted, best available.
pub async fn get_track_file_default(
    State(state): State<AppState>,
    Path(track_id): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state.system.cancion_archivo_default(&track_id, bw).await;
    serve_outcome(&headers, outcome).await
}

/// `GET /deezer/tracks/{track_id}/file/{format}/only-cache`.
pub async fn get_track_file_only_cache(
    State(state): State<AppState>,
    Path((track_id, raw_format)): Path<(String, String)>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state
        .system
        .cancion_archivo_solo_cache(&track_id, &raw_format, bw)
        .await;
    serve_outcome(&headers, outcome).await
}

/// `GET /deezer/tracks/{track_id}/file/only-cache` — format omitted.
pub async fn get_track_file_only_cache_default(
    State(state): State<AppState>,
    Path(track_id): Path<String>,
    headers: HeaderMap,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let outcome = state
        .system
        .cancion_archivo_solo_cache_default(&track_id, bw)
        .await;
    serve_outcome(&headers, outcome).await
}

/// `getAutocompleteHandler` — `GET /deezer/autocomplete?q&limit`.
pub async fn get_autocomplete(
    State(state): State<AppState>,
    RawQuery(raw): RawQuery,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let mut result = ResultEnvelope::<Value>::new();

    let parsed = parse_search_query(raw.as_deref());
    tracing::debug!(
        target: "DEEZER",
        q = %parsed.q,
        limit = parsed.limit,
        "getAutocomplete controller input"
    );
    if !parsed.errors.is_empty() {
        for message in parsed.errors {
            result.add_error(&validation_error(message));
        }
        return result.into_response();
    }

    let data = state
        .system
        .autocompletar(&parsed.q, Some(parsed.limit as u32), bw)
        .await;
    tracing::debug!(
        target: "DEEZER",
        q = %parsed.q,
        limit = parsed.limit,
        "getAutocomplete controller response"
    );
    result.add_data(data);
    result.into_response()
}

/// `getSearchHandler` — `GET /deezer/search?q&limit`.
pub async fn get_search(
    State(state): State<AppState>,
    RawQuery(raw): RawQuery,
    bw: Option<Extension<BandwidthOp>>,
) -> Response {
    let bw = bw.as_ref().map(|extension| &extension.0);
    let mut result = ResultEnvelope::<Value>::new();

    let parsed = parse_search_query(raw.as_deref());
    tracing::debug!(
        target: "DEEZER",
        q = %parsed.q,
        limit = parsed.limit,
        "getSearch controller input"
    );
    if !parsed.errors.is_empty() {
        for message in parsed.errors {
            result.add_error(&validation_error(message));
        }
        return result.into_response();
    }

    let data = state
        .system
        .buscar_canciones(&parsed.q, Some(parsed.limit as u32), bw)
        .await;
    tracing::debug!(
        target: "DEEZER",
        q = %parsed.q,
        limit = parsed.limit,
        "getSearch controller response"
    );
    result.add_data(data);
    result.into_response()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_int_prefix_mirrors_number_parse_int() {
        assert_eq!(parse_int_prefix("10"), Some(10));
        assert_eq!(parse_int_prefix("  25 "), Some(25));
        assert_eq!(parse_int_prefix("5x"), Some(5));
        assert_eq!(parse_int_prefix("-3"), Some(-3));
        assert_eq!(parse_int_prefix("+7"), Some(7));
        assert_eq!(parse_int_prefix("abc"), None);
        assert_eq!(parse_int_prefix(""), None);
        assert_eq!(parse_int_prefix("x9"), None);
    }

    #[test]
    fn search_query_first_value_and_defaults() {
        let parsed = parse_search_query(Some("q=a&q=b&limit=5"));
        assert_eq!(parsed.q, "a");
        assert_eq!(parsed.limit, 5);
        assert!(parsed.errors.is_empty());

        // Missing limit selects the default without erroring.
        let parsed = parse_search_query(Some("q=daft%20punk"));
        assert_eq!(parsed.limit, SEARCH_LIMIT_DEFAULT);
        assert!(parsed.errors.is_empty());

        // Unparseable limit is NaN in TS and also selects the default.
        let parsed = parse_search_query(Some("q=x&limit=abc"));
        assert_eq!(parsed.limit, SEARCH_LIMIT_DEFAULT);
        assert!(parsed.errors.is_empty());
    }

    #[test]
    fn search_query_validation_errors() {
        let parsed = parse_search_query(None);
        assert_eq!(parsed.errors, vec!["Query parameter `q` is required"]);

        // Zero-width-only q normalizes to empty -> 400 (never reaches Deezer).
        let parsed = parse_search_query(Some("q=%E2%80%8B%E2%80%8B"));
        assert_eq!(parsed.errors, vec!["Query parameter `q` is required"]);

        let parsed = parse_search_query(Some("q=x&limit=0"));
        assert_eq!(
            parsed.errors,
            vec!["Query parameter `limit` must be between 1 and 25"]
        );
        let parsed = parse_search_query(Some("q=x&limit=26"));
        assert_eq!(parsed.errors.len(), 1);
    }
}

