1	//! Orquestación de archivos Deezer — movida desde `http/controllers/deezer.rs`
2	//! (Fase 2 del plan). Lógica idéntica; lo único que cambia es la frontera:
3	//! aquí no hay tipos de axum. El frontend HTTP aplica Range/streaming sobre
4	//! el `AudioServe::File` devuelto.
5	//!
6	//! Contrato observable (espejo exacto del TS, ver docs/CASOS_DE_USO.md):
7	//! - archivo (formato explícito): lock de descarga acotado (3 intentos,
8	//!   esperas de 60 s, 503 en contención), short-circuit de fs-cache en cada
9	//!   acquire/despertar, heartbeat de extensión del lock cada 15 s durante la
10	//!   descarga, gate mp3val, manifiesto, contador `deezer` y archivo listo.
11	//! - archivo (formato omitido): resuelve el mejor formato que el track
12	//!   expone (`FILESIZE_*` > 0, FLAC → MP3 → AAC) y corre el mismo pipeline;
13	//!   404 sin formato; retry sin FLAC ante 403 `format_rights`.
14	//! - solo-caché: probe de fs, nunca descarga; marca cache-hit de bandwidth
15	//!   incluso en miss (paridad TS — gap 1 del catálogo, se corrige en Fase 3).
16	//! - tokens: tokens de sesión + token de track cacheado (TTL dinámico de
17	//!   Deezer), 401 en errores de licencia, 500 en fallos de transporte.
18	
19	use std::path::Path as FsPath;
20	use std::sync::Arc;
21	use std::time::Duration;
22	
23	use serde::Serialize;
24	use serde_json::Value;
25	
26	use crate::audio::{
27	    calculate_key, download_deezer_track, fix_file, validate_directory, validate_file,
28	    DownloadError, DownloadParams, TrackId3Metadata,
29	};
30	use crate::cache::keys::deezer_track_token_key;
31	use crate::cache::locks::{DownloadLock, DownloadLockGuard};
32	use crate::cache::manifest::{self, FileManifestEntry};
33	use crate::clients::TrackCounterSource;
34	use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
35	use crate::providers::deezer::{deezer_image_url, token_related_ttl, DeezerArlFailureContext};
36	use crate::telemetry::{BandwidthOp, BandwidthProvider, CacheMark};
37	
38	use super::result::AudioServe;
39	use super::MusicSystem;
40	
41	/// Bounded lock retry (deezer-controller.ts:359-361): cap so a poisoned lock
42	/// degrades to 503 instead of holding the socket open forever.
43	const MAX_LOCK_ATTEMPTS: u32 = 3;
44	const LOCK_WAIT_MS: u64 = 60_000;
45	/// `setInterval(extend, 15_000)` heartbeat while a download holds the lock.
46	const LOCK_EXTEND_INTERVAL: Duration = Duration::from_millis(15_000);
47	/// Thumbnail fetch budget in `buildDeezerId3Metadata` (5 s AbortController).
48	const THUMBNAIL_TIMEOUT: Duration = Duration::from_secs(5);
49	const DOWNLOAD_OVERALL_TIMEOUT_MS: u64 = 60_000;
50	const DOWNLOAD_CHUNK_TIMEOUT_MS: u64 = 10_000;
51	
52	// ---------------------------------------------------------------------------
53	// Format registry (`shared/lib/deezer-formats.ts` + shared alias table)
54	// ---------------------------------------------------------------------------
55	
56	/// `DeezerFormatSpec`: everything the download pipeline needs per container.
57	pub struct DeezerFormatSpec {
58	    /// Canonical token used for cache/lock keys and logs.
59	    pub token: &'static str,
60	    /// On-disk extension (with leading dot) — also the file-cache suffix.
61	    pub extension: &'static str,
62	    /// HTTP Content-Type served to the client / Lavalink.
63	    pub content_type: &'static str,
64	    /// Container family for validation + tagging (`mp3` | `flac` | `mp4`).
65	    pub container: &'static str,
66	    /// Deezer `get_url` format priority list.
67	    pub deezer_formats: &'static [&'static str],
68	}
69	
70	pub static MP3: DeezerFormatSpec = DeezerFormatSpec {
71	    token: "mp3",
72	    extension: ".mp3",
73	    content_type: "audio/mpeg",
74	    container: "mp3",
75	    deezer_formats: &["MP3_320", "MP3_256", "MP3_128", "MP3_64"],
76	};
77	
78	pub static FLAC: DeezerFormatSpec = DeezerFormatSpec {
79	    token: "flac",
80	    extension: ".flac",
81	    content_type: "audio/flac",
82	    container: "flac",
83	    deezer_formats: &["FLAC"],
84	};
85	
86	pub static AAC: DeezerFormatSpec = DeezerFormatSpec {
87	    token: "aac",
88	    extension: ".m4a",
89	    content_type: "audio/mp4",
90	    container: "mp4",
91	    deezer_formats: &["AAC_64"],
92	};
93	
94	/// `resolveDeezerFormat(raw)` — alias → spec, `None` when unsupported
95	/// (callers return 400). Accepts leading dots and any case.
96	pub fn resolve_deezer_format(raw: &str) -> Option<&'static DeezerFormatSpec> {
97	    let key = raw.trim().to_lowercase();
98	    let key = key.trim_start_matches('.');
99	    match key {
100	        "mp3" | "mp3_320" | "mp3_256" | "mp3_128" | "mp3_64" => Some(&MP3),
101	        "flac" => Some(&FLAC),
102	        "aac" | "aac_64" | "m4a" | "mp4" => Some(&AAC),
103	        _ => None,
104	    }
105	}
106	
107	/// Availability probe order for requests that omit `{format}`: highest
108	/// quality first. Deezer reports `FILESIZE_* = 0` (or omits the field) when
109	/// the track cannot be served in that format for the active ARL.
110	static DEFAULT_FORMAT_PRIORITY: [(&str, &DeezerFormatSpec); 6] = [
111	    ("FILESIZE_FLAC", &FLAC),
112	    ("FILESIZE_MP3_320", &MP3),
113	    ("FILESIZE_MP3_256", &MP3),
114	    ("FILESIZE_MP3_128", &MP3),
115	    ("FILESIZE_MP3_64", &MP3),
116	    ("FILESIZE_AAC_64", &AAC),
117	];
118	
119	/// Pick the best available spec from the track's song data (`FILESIZE_*`
120	/// fields). `None` when the track exposes no downloadable format.
121	pub fn resolve_default_deezer_format(results: &Value) -> Option<&'static DeezerFormatSpec> {
122	    resolve_from_priority(results, &DEFAULT_FORMAT_PRIORITY)
123	}
124	
125	/// Same resolution but skipping FLAC — the 403-downgrade retry: cached
126	/// `FILESIZE_*` can promise FLAC that the *current* ARL can no longer serve
127	/// (tier rotation), and a propagated 403 would dead-stamp the track for 72 h
128	/// upstream even though MP3 works.
129	pub fn resolve_default_deezer_format_no_flac(results: &Value) -> Option<&'static DeezerFormatSpec> {
130	    resolve_from_priority(results, &DEFAULT_FORMAT_PRIORITY[1..])
131	}
132	
133	fn resolve_from_priority(
134	    results: &Value,
135	    priority: &[(&str, &'static DeezerFormatSpec)],
136	) -> Option<&'static DeezerFormatSpec> {
137	    priority
138	        .iter()
139	        .find(|(key, _)| filesize_field(results, key) > 0)
140	        .map(|(_, spec)| *spec)
141	}
142	
143	/// Deezer serialises `FILESIZE_*` as strings (`"0"` = unavailable), but some
144	/// payloads carry plain numbers — accept both, anything else counts as 0.
145	fn filesize_field(results: &Value, key: &str) -> u64 {
146	    match results.get(key) {
147	        Some(Value::String(raw)) => raw.trim().parse().unwrap_or(0),
148	        Some(value) => value.as_u64().unwrap_or(0),
149	        None => 0,
150	    }
151	}
152	
153	/// The deezer format names in `DEFAULT_FORMAT_PRIORITY`, order preserved
154	/// (bitrate duplicates kept — Deezer echoes back whichever one it grants).
155	fn combined_deezer_formats() -> Vec<&'static str> {
156	    DEFAULT_FORMAT_PRIORITY
157	        .iter()
158	        .map(|(key, _)| key.strip_prefix("FILESIZE_").unwrap_or(key))
159	        .collect()
160	}
161	
162	/// Map the deezer format names Deezer actually granted back to canonical
163	/// tokens, in `DEFAULT_FORMAT_PRIORITY` order and deduped (every `MP3_*`
164	/// bitrate collapses to a single `mp3`).
165	fn granted_formats_to_tokens(granted: &[String]) -> Vec<&'static str> {
166	    let mut tokens: Vec<&'static str> = Vec::new();
167	    for (key, spec) in DEFAULT_FORMAT_PRIORITY.iter() {
168	        let name = key.strip_prefix("FILESIZE_").unwrap_or(key);
169	        if granted.iter().any(|g| g.eq_ignore_ascii_case(name)) && !tokens.contains(&spec.token) {
170	            tokens.push(spec.token);
171	        }
172	    }
173	    tokens
174	}
