238	/// Build the ID3 payload for the download pipeline. Cover art is fetched
239	/// here (5 s budget); any network failure just drops the image — it never
240	/// blocks the cache write.
241	async fn build_deezer_id3_metadata(
242	    http: &reqwest::Client,
243	    track: &Value,
244	    track_id: &str,
245	    default_image: &str,
246	) -> TrackId3Metadata {
247	    let s = |key: &str| track.get(key).and_then(Value::as_str).unwrap_or("");
248	
249	    let song_title = match s("SNG_TITLE") {
250	        "" => "Unknown Title",
251	        title => title,
252	    };
253	    let uploader_name = match s("ART_NAME") {
254	        "" => "Unknown Artist",
255	        name => name,
256	    };
257	    let artist = match track.get("ARTISTS").and_then(Value::as_array) {
258	        Some(artists) if !artists.is_empty() => artists
259	            .iter()
260	            .map(|a| a.get("ART_NAME").and_then(Value::as_str).unwrap_or(""))
261	            .collect::<Vec<_>>()
262	            .join(", "),
263	        _ => uploader_name.to_string(),
264	    };
265	
266	    let thumbnail_url = match s("ALB_PICTURE") {
267	        "" => default_image.to_string(),
268	        picture => deezer_image_url(picture, "250x250"),
269	    };
270	
271	    let mut image_jpeg = None;
272	    if !thumbnail_url.is_empty() {
273	        let fetch = async {
274	            let response = http.get(&thumbnail_url).send().await?;
275	            if response.status().is_success() {
276	                response.bytes().await.map(Some)
277	            } else {
278	                Ok(None)
279	            }
280	        };
281	        match tokio::time::timeout(THUMBNAIL_TIMEOUT, fetch).await {
282	            Ok(Ok(Some(bytes))) => image_jpeg = Some(bytes.to_vec()),
283	            Ok(Ok(None)) => {}
284	            Ok(Err(error)) => {
285	                let error: reqwest::Error = error;
286	                tracing::warn!(target: "DEEZER", error = %error, "Failed to download thumbnail");
287	            }
288	            Err(_) => {
289	                tracing::warn!(target: "DEEZER", "Failed to download thumbnail: timeout");
290	            }
291	        }
292	    }
293	
294	    let year = track
295	        .get("PHYSICAL_RELEASE_DATE")
296	        .and_then(Value::as_str)
297	        .and_then(|date| date.get(..4))
298	        .and_then(|y| y.parse::<i32>().ok());
299	
300	    let duration_ms = track
301	        .get("DURATION")
302	        .and_then(Value::as_str)
303	        .and_then(|seconds| seconds.parse::<u32>().ok())
304	        .map(|seconds| seconds * 1000);
305	
306	    TrackId3Metadata {
307	        title: Some(song_title.to_string()),
308	        artist: Some(artist),
309	        album: Some(match s("ALB_TITLE") {
310	            "" => uploader_name.to_string(),
311	            album => album.to_string(),
312	        }),
313	        year,
314	        duration_ms,
315	        source: Some("deezer".to_string()),
316	        track_id: Some(track_id.to_string()),
317	        isrc: track.get("ISRC").and_then(Value::as_str).map(str::to_owned),
318	        comment: Some(thumbnail_url),
319	        image_jpeg,
320	    }
321	}
