460	    /// Caso 4 — formatos disponibles (probe en vivo, nunca cacheado).
461	    pub async fn cancion_formatos(
462	        &self,
463	        track_id: &str,
464	        bw: Option<&BandwidthOp>,
465	    ) -> ResultEnvelope<AvailableFormatsData> {
466	        let mut result = ResultEnvelope::<AvailableFormatsData>::new();
467	
468	        if !is_numeric_track_id(track_id) {
469	            result.add_error(&validation_error("Valid numeric Track ID is required"));
470	            return result;
471	        }
472	
473	        let deezer_formats = combined_deezer_formats();
474	
475	        let granted = match self
476	            .deezer
477	            .get_available_formats(track_id, &deezer_formats, bw)
478	            .await
479	        {
480	            Ok(granted) => granted,
481	            Err(errors) => {
482	                for error in &errors {
483	                    result.add_error(error);
484	                }
485	                return result;
486	            }
487	        };
488	
489	        // Priority-ordered, deduped canonical tokens.
490	        let formats = granted_formats_to_tokens(&granted);
491	
492	        if formats.is_empty() {
493	            result.add_error(
494	                &ApiError::new(
495	                    "No available track format",
496	                    ErrorType::Service,
497	                    ErrorContext::Api,
498	                )
499	                .with_status(404),
500	            );
501	            return result;
502	        }
503	
504	        result.add_data(AvailableFormatsData { formats });
505	        result
506	    }
