535	    /// Caso 6 — archivo con formato omitido: mejor disponible (FLAC → MP3 →
536	    /// AAC) por `FILESIZE_*`, con retry sin FLAC ante 403 `format_rights`.
537	    pub async fn cancion_archivo_default(
538	        &self,
539	        track_id: &str,
540	        bw: Option<&BandwidthOp>,
541	    ) -> AudioServe {
542	        tracing::debug!(target: "DEEZER", track_id, "getTrackFileDefault controller input");
543	        if !is_numeric_track_id(track_id) {
544	            return AudioServe::Fail(fail_with(&[validation_error(
545	                "Valid numeric Track ID is required",
546	            )]));
547	        }
548	
549	        let song_data = match self.deezer.get_track_data(track_id, bw).await {
550	            Ok(data) => data,
551	            Err(errors) => return AudioServe::Fail(fail_with(&errors)),
552	        };
553	        let Some(spec) = resolve_default_deezer_format(&song_data) else {
554	            return AudioServe::Fail(fail_with(&[ApiError::new(
555	                "No available track format",
556	                ErrorType::Service,
557	                ErrorContext::Api,
558	            )
559	            .with_status(404)]));
560	        };
561	        tracing::debug!(
562	            target: "DEEZER",
563	            track_id,
564	            track_format = spec.extension,
565	            "getTrackFileDefault resolved format"
566	        );
567	
568	        let outcome = self.serve_track_file(track_id.to_string(), spec, bw).await;
569	
570	        // 403-downgrade guard: cached FILESIZE_* promised FLAC but the current
571	        // ARL can't serve it (tier rotation / rights). A propagated 403 would
572	        // let api-music dead-stamp the track (`available_buffer=false`, 72 h)
573	        // even though a lower format works — and in auto mode nobody upstream
574	        // retries. One retry with the best non-FLAC format; explicit
575	        // `/file/flac` keeps its plain-403 semantics. (El controlador original
576	        // inspeccionaba `x-error-code` en la Response; ese header lo emite el
577	        // envelope, así que aquí se lee la misma señal en origen.)
578	        if spec.token == "flac" && is_format_rights_403(&outcome) {
579	            if let Some(fallback) = resolve_default_deezer_format_no_flac(&song_data) {
580	                tracing::warn!(
581	                    target: "DEEZER",
582	                    track_id,
583	                    fallback_format = fallback.extension,
584	                    "FLAC download forbidden (403) — retrying with fallback format"
585	                );
586	                return self.serve_track_file(track_id.to_string(), fallback, bw).await;
587	            }
588	        }
589	        outcome
590	    }
