655	    /// Caso 8 — solo-caché con formato omitido: probe FLAC → MP3 → AAC,
656	    /// primer hit gana. Nunca descarga y nunca llama a Deezer.
657	    pub async fn cancion_archivo_solo_cache_default(
658	        &self,
659	        track_id: &str,
660	        bw: Option<&BandwidthOp>,
661	    ) -> AudioServe {
662	        tracing::debug!(
663	            target: "DEEZER",
664	            track_id,
665	            "getTrackFileOnlyCacheDefault controller input"
666	        );
667	        if !is_numeric_track_id(track_id) {
668	            return AudioServe::Fail(fail_with(&[validation_error(
669	                "Valid numeric Track ID is required",
670	            )]));
671	        }
672	
673	        // TS parity with the explicit-format probe: mark a bandwidth cache-hit
674	        // even when every extension misses.
675	        if let Some(op) = bw {
676	            op.set_provider(BandwidthProvider::Deezer);
677	            op.mark_cache(CacheMark::Hit);
678	        }
679	
680	        for spec in [&FLAC, &MP3, &AAC] {
681	            let Some(file_path) = self.disk.deezer_cache_path(track_id, spec.extension) else {
682	                continue;
683	            };
684	            let Ok(stat) = tokio::fs::metadata(&file_path).await else {
685	                continue;
686	            };
687	            tracing::info!(
688	                target: "DEEZER",
689	                track_id,
690	                track_format = spec.extension,
691	                origin = "deezer",
692	                file_size = stat.len(),
693	                "track file source: fs cache (probe only, default format)"
694	            );
695	            return AudioServe::File {
696	                path: file_path,
697	                content_type: spec.content_type,
698	            };
699	        }
700	
701	        AudioServe::Fail(fail_with(&[ApiError::new(
702	            "Track file not found in cache",
703	            ErrorType::Unknown,
704	            ErrorContext::Api,
705	        )
706	        .with_status(404)]))
707	    }
