1109	    fn no_flac_fallback_skips_flac_and_keeps_priority() {
1110	        // The `[1..]` slice in `resolve_default_deezer_format_no_flac` relies
1111	        // on FLAC being the FIRST priority entry — guard the invariant.
1112	        assert_eq!(DEFAULT_FORMAT_PRIORITY[0].1.token, "flac");
1113	
1114	        // FLAC promised but forbidden -> best MP3 wins on the retry path.
1115	        let full = serde_json::json!({
1116	            "FILESIZE_FLAC": "12345",
1117	            "FILESIZE_MP3_320": "999",
1118	            "FILESIZE_AAC_64": "111",
1119	        });
1120	        assert_eq!(
1121	            resolve_default_deezer_format_no_flac(&full).unwrap().token,
1122	            "mp3"
1123	        );
