1125	        // FLAC-only track -> no fallback (retry must not loop).
1126	        let flac_only = serde_json::json!({ "FILESIZE_FLAC": "12345" });
1127	        assert!(resolve_default_deezer_format_no_flac(&flac_only).is_none());
1128	
1129	        // AAC-only -> fallback still finds it.
1130	        let aac_only = serde_json::json!({ "FILESIZE_AAC_64": 111 });
1131	        assert_eq!(
1132	            resolve_default_deezer_format_no_flac(&aac_only)
1133	                .unwrap()
1134	                .token,
