//! Orquestación de archivos Chipbot — movida desde `http/controllers/chipbot.rs`
//! (mismo patrón que la Fase 2 aplicada a Deezer en `system::deezer_files`).
//! Lógica idéntica; lo único que cambia es la frontera: aquí no hay tipos de
//! axum. El frontend HTTP aplica Range/streaming sobre el `AudioServe::File`
//! devuelto.
//!
//! Contrato observable (espejo exacto del TS):
//! - archivo (ISRC + formato, explícito u omitido -> mp3 por defecto): probe
//!   de fs-cache primero (todas las extensiones de audio soportadas); en
//!   miss, resuelve el track vía Chipbot, descarga a un tmp file (rename
//!   atómico), etiqueta ID3 en mp3, escribe el manifiesto y dispara el
//!   contador `chipbot`.
//! - solo-caché: mismo probe de fs, nunca llama a Chipbot ni descarga; 404
//!   si no hay archivo cacheado.
//! - errores de red/fs se propagan como `Err(String)`; el frontend los
//!   traduce a 500 con la causa adjunta.

use std::ffi::OsString;
use std::path::{Path as FsPath, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use futures_util::StreamExt;
use id3::{Tag, TagLike, Version};
use tokio::io::AsyncWriteExt;
use url::Url;

use crate::audio::disk::{
    audio_content_type, is_audio_extension, normalize_isrc, validate_directory, validate_file,
    AUDIO_EXTENSIONS,
};
use crate::cache::manifest::{self, FileManifestEntry};
use crate::clients::TrackCounterSource;
use crate::error::{ApiError, ErrorContext, ErrorType, ResultEnvelope};
use crate::providers::chipbot::ChipbotTrack;
use crate::telemetry::{BandwidthOp, BandwidthProvider, CacheMark};

use super::result::AudioServe;
use super::MusicSystem;

const CHIPBOT_FETCH_TIMEOUT_MS: u64 = 15_000;

#[derive(Debug)]
struct FileRequestValidation {
    isrc: Option<String>,
    requested_format: String,
    errors: ResultEnvelope<()>,
}

fn requested_extension(raw_format: &str) -> String {
    if raw_format.starts_with('.') {
        raw_format.to_string()
    } else {
        format!(".{raw_format}")
    }
}

fn validate_file_request(raw_isrc: &str, raw_format: &str) -> FileRequestValidation {
    let isrc = normalize_isrc(raw_isrc);
    let requested_format = requested_extension(raw_format);
    let mut errors = ResultEnvelope::<()>::new();

    if isrc.is_none() {
        errors.add_error(
            &ApiError::new(
                "Valid ISRC is required",
                ErrorType::Validation,
                ErrorContext::Api,
            )
            .with_status(400),
        );
    }
    if !is_audio_extension(&requested_format) {
        errors.add_error(
            &ApiError::new(
                "Invalid track format",
                ErrorType::Validation,
                ErrorContext::Api,
            )
            .with_status(400),
        );
    }

    FileRequestValidation {
        isrc,
        requested_format,
        errors,
    }
}

fn cache_filename(isrc: &str, extension: &str) -> Option<String> {
    let isrc = normalize_isrc(isrc)?;
    is_audio_extension(extension).then(|| format!("{isrc}{extension}"))
}

fn manifest_filename(isrc: &str, extension: &str) -> Option<String> {
    cache_filename(isrc, extension).map(|filename| format!("tmp-chipbot/{filename}"))
}

fn audio_extension_from_url(url: &Url) -> Option<&'static str> {
    let path = url.path();
    let requested = match path.rfind('.') {
        Some(dot) if dot + 1 < path.len() => &path[dot..],
        _ => ".mp3",
    };
    AUDIO_EXTENSIONS
        .iter()
        .copied()
        .find(|extension| *extension == requested)
}

fn allowed_audio_url(raw: &str) -> Option<Url> {
    let url = Url::parse(raw).ok()?;
    matches!(url.scheme(), "http" | "https").then_some(url)
}

fn tmp_path_for(path: &FsPath) -> PathBuf {
    let mut tmp = OsString::from(path.as_os_str());
    tmp.push(".tmp");
    PathBuf::from(tmp)
}

fn now_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().min(i64::MAX as u128) as i64)
        .unwrap_or(0)
}

fn not_found(message: String) -> ResultEnvelope<()> {
    let mut result = ResultEnvelope::<()>::new();
    result.add_error(&ApiError::new(message, ErrorType::Unknown, ErrorContext::Api).with_status(404));
    result
}

fn write_chipbot_id3(path: &FsPath, isrc: &str, origin_url: &str) -> Result<(), id3::Error> {
    let mut tag = Tag::new();
    tag.add_frame(id3::frame::Comment {
        lang: "eng".to_string(),
        description: String::new(),
        text: origin_url.to_string(),
    });
    for (description, value) in [
        ("source", "chipbot"),
        ("isrc", isrc),
        ("origin_url", origin_url),
    ] {
        tag.add_frame(id3::frame::ExtendedText {
            description: description.to_string(),
            value: value.to_string(),
        });
    }
    tag.write_to_path(path, Version::Id3v23)
}

impl MusicSystem {
    /// Probe de fs-cache compartido por los flujos de descarga y solo-caché:
    /// primera extensión de audio con archivo válido gana.
    async fn chipbot_cached_file(&self, isrc: &str, bw: Option<&BandwidthOp>) -> Option<AudioServe> {
        for extension in AUDIO_EXTENSIONS {
            let path = self.disk.chipbot_cache_path(isrc, extension)?;
            if !validate_file(&path).await {
                continue;
            }

            tracing::info!(
                target: "CHIPBOT",
                isrc,
                extension,
                origin = "chipbot",
                "audio source: CHIPBOT fs cache"
            );
            if let Some(op) = bw {
                op.set_provider(BandwidthProvider::Chipbot);
                op.mark_cache(CacheMark::Hit);
            }
            return Some(AudioServe::File {
                path,
                content_type: audio_content_type(extension),
            });
        }
        None
    }

    async fn cache_chipbot_track(
        &self,
        track: &ChipbotTrack,
        isrc: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<Option<PathBuf>, String> {
        let Some(audio) = track.audio.as_ref().filter(|audio| !audio.url.is_empty()) else {
            return Ok(None);
        };
        let Some(url) = allowed_audio_url(&audio.url) else {
            return Ok(None);
        };
        let Some(extension) = audio_extension_from_url(&url) else {
            return Ok(None);
        };
        let Some(file_path) = self.disk.chipbot_cache_path(isrc, extension) else {
            return Ok(None);
        };

        validate_directory(&self.disk.chipbot)
            .await
            .map_err(|error| format!("create Chipbot cache directory: {error}"))?;

        if let Some(op) = bw {
            op.add_upstream_requests(1);
        }
        let request = self.http.get(url).header(reqwest::header::ACCEPT, "*/*");
        let response = tokio::time::timeout(
            Duration::from_millis(CHIPBOT_FETCH_TIMEOUT_MS),
            request.send(),
        )
        .await
        .map_err(|_| "This operation was aborted".to_string())?
        .map_err(|error| format!("Chipbot audio fetch failed: {error}"))?;
        if let (Some(op), Some(bytes)) = (bw, response.content_length().filter(|bytes| *bytes > 0)) {
            op.add_upstream_received(bytes);
        }
        if !response.status().is_success() {
            return Err(format!(
                "Chipbot audio fetch failed: HTTP {}",
                response.status().as_u16()
            ));
        }

        let tmp_path = tmp_path_for(&file_path);
        let stream_result: Result<(), String> = async {
            let mut file = tokio::fs::File::create(&tmp_path)
                .await
                .map_err(|error| format!("create Chipbot temp file: {error}"))?;
            let mut stream = response.bytes_stream();
            while let Some(chunk) = stream.next().await {
                let chunk = chunk.map_err(|error| format!("read Chipbot audio stream: {error}"))?;
                file.write_all(&chunk)
                    .await
                    .map_err(|error| format!("write Chipbot temp file: {error}"))?;
            }
            file.flush()
                .await
                .map_err(|error| format!("flush Chipbot temp file: {error}"))?;
            drop(file);
            tokio::fs::rename(&tmp_path, &file_path)
                .await
                .map_err(|error| format!("rename Chipbot cache file: {error}"))?;
            Ok(())
        }
        .await;
        if let Err(error) = stream_result {
            let _ = tokio::fs::remove_file(&tmp_path).await;
            return Err(error);
        }

        if extension == ".mp3" {
            let tag_path = file_path.clone();
            let tag_isrc = isrc.to_string();
            let origin_url = audio.url.clone();
            match tokio::task::spawn_blocking(move || {
                write_chipbot_id3(&tag_path, &tag_isrc, &origin_url)
            })
            .await
            {
                Ok(Ok(())) => {}
                Ok(Err(error)) => tracing::warn!(
                    target: "CHIPBOT",
                    isrc,
                    error = %error,
                    "Failed to write Chipbot ID3 tags"
                ),
                Err(error) => tracing::warn!(
                    target: "CHIPBOT",
                    isrc,
                    error = %error,
                    "Failed to write Chipbot ID3 tags"
                ),
            }
        }

        let size = tokio::fs::metadata(&file_path)
            .await
            .map_err(|error| format!("stat downloaded Chipbot file: {error}"))?
            .len();
        let manifest_name = manifest_filename(isrc, extension)
            .ok_or_else(|| "invalid Chipbot manifest filename".to_string())?;
        manifest::set_entry(
            &self.redis,
            &manifest_name,
            &FileManifestEntry {
                source: Some("chipbot".to_string()),
                isrc: Some(isrc.to_string()),
                size: Some(size),
                cached_at: Some(now_ms()),
                ..Default::default()
            },
        )
        .await
        .map_err(|error| format!("write Chipbot file manifest: {error}"))?;

        Ok(Some(file_path))
    }

    /// Archivo Chipbot por ISRC — formato explícito o `mp3` por defecto
    /// (`getTrackFileByIsrcHandler` / `getTrackFileByIsrcDefaultHandler`).
    pub async fn chipbot_archivo(
        &self,
        raw_isrc: &str,
        raw_format: &str,
        bw: Option<&BandwidthOp>,
    ) -> Result<AudioServe, String> {
        let FileRequestValidation {
            isrc,
            requested_format,
            errors,
        } = validate_file_request(raw_isrc, raw_format);
        tracing::debug!(
            target: "CHIPBOT",
            isrc = ?isrc,
            raw_isrc,
            raw_format,
            requested_format,
            "getTrackFileByIsrc controller input"
        );
