use crate::telemetry::BandwidthOp;

fn internal_error_response(cause: String) -> Response {
    let error = ApiError::new(
        "Internal server error",
        ErrorType::Internal,
        ErrorContext::Api,
    )
    .with_status(500)
    .with_cause(cause);
    let mut result = ResultEnvelope::<()>::new();
    result.add_error(&error);
    result.into_response()
}

/// Stream the cached file honouring `Range` (the `sendFile` surface).
async fn send_cached_file(
    headers: &HeaderMap,
    path: &FsPath,
    content_type: &str,
) -> Result<Response, String> {
    let metadata = tokio::fs::metadata(path)
        .await
        .map_err(|error| format!("stat cached Chipbot file: {error}"))?;
    let range = headers
        .get(header::RANGE)
        .map(|value| value.to_str().unwrap_or(""));
    let outcome = parse_range(range, metadata.len());
    Ok(file_response(path, metadata.len(), outcome, content_type, HeaderMap::new()).await)
}

/// Traducción `AudioServe` -> HTTP: archivo con Range, fallo como envelope.
async fn serve_outcome(headers: &HeaderMap, outcome: AudioServe) -> Result<Response, String> {
    match outcome {
        AudioServe::File { path, content_type } => {
            send_cached_file(headers, &path, content_type).await
        }
        AudioServe::Fail(envelope) => Ok(envelope.into_response()),
    }
}

