impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        let mut envelope = ResultEnvelope::<serde_json::Value>::new();
        envelope.add_error(&self);
        // `ResultEnvelope::into_response` emits `x-error-code`; layer the
        // `x-error-type` header (this error's own context) on top.
        let mut response = envelope.into_response();
        if let Some(context) = self.context_header {
            if let Ok(value) = HeaderValue::from_str(context.as_str()) {
                response.headers_mut().insert("x-error-type", value);
            }
        }
        response
    }
}

